/// <summary>
/// The service class for the batch job
/// </summary>
class METBackOrderProcessingService extends SysOperationServiceBase
{
}

Method.Source:
    /// CB425 BuyBackOrders
    /// <summary>
    /// The process method for the back orders processing
    /// </summary>
    /// <param name = "_contract">The data contract object</param>
    public void processOperation(METBackOrderProcessingDataContract _contract)
    {
        utcdatetime currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimezone());
        
        date startDate;
        date endDate =  DateTimeUtil::date(currentDateTime);
        int totalDays;

        Query query = _contract.getQuery();
        PurchId purchId = _contract.parmPurchId();
        
        QueryBuildDataSource qbdsPurchTable = query.dataSourceTable(tableNum(InventSite)).addDataSource(tableNum(PurchTable));
        qbdsPurchTable.relations(true);
        qbdsPurchTable.joinMode(JoinMode::InnerJoin);
        qbdsPurchTable.addRange(fieldNum(PurchTable, PurchStatus)).value(queryValue(PurchStatus::Backorder));
        
        if (strLen(purchId) > 0
            && PurchTable::find(purchId).RecId)
        {
            qbdsPurchTable.addRange(fieldNum(PurchTable, PurchId)).value(queryValue(purchId));
        }
       
        QueryBuildDataSource qbdsMetPurchTable = qbdsPurchTable.addDataSource(tableNum(MetPurchTable));
        qbdsMetPurchTable.relations(true);
        qbdsMetPurchTable.joinMode(JoinMode::InnerJoin);
        
        QueryRun queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            InventSite inventSite = queryRun.get(tableNum(InventSite));
            PurchTable purchTable = queryRun.get(tableNum(PurchTable));
            METPurchTable metPurchTable = queryRun.get(tableNum(MetPurchTable));

            if (metPurchTable.ProcessingErrorCount <= METVendParameters::find().POBackOrderProcessingRetryCount)
            {
                try
                {
                    VendPackingSlipJour vendPackingSlipJour;
                    boolean dateGreaterThanTolerance;

                    select firstonly RecId, DeliveryDate from vendPackingSlipJour
                    order by DeliveryDate desc
                    where vendPackingSlipJour.PurchId == purchTable.PurchId;

                    if (metPurchTable.POBackOrderSetting == noyes::Yes && vendPackingSlipJour.RecId != 0)
                    {
                        startDate = vendPackingSlipJour.DeliveryDate;
                        totalDays = endDate - startDate; //Calculate number of days from today to last posted product receipt including weekends.

                        dateGreaterThanTolerance = totalDays >= inventSite.METPOBackOrderBatchJobDays;
                
                        if (dateGreaterThanTolerance && vendPackingSlipJour.DeliveryDate != DateTimeUtil::date(DateTimeUtil::minValue()))
                        {
                            this.getPurchOrderLinesAndupdateDeliveryRemainder(purchTable.PurchId);
                        }
                    }
                    else if (vendPackingSlipJour.RecId == 0 && metPurchTable.POBackOrderSetting == noyes::Yes)
                    {
                        startDate = purchTable.DeliveryDate;
                        totalDays = endDate - startDate; //Calculate number of days from today to receipt date including weekends.

                        dateGreaterThanTolerance = totalDays >= inventSite.METPOBackOrderBatchJobDays;
    
                        if (dateGreaterThanTolerance && purchTable.DeliveryDate != DateTimeUtil::date(DateTimeUtil::minValue()))
                        {
                            this.getPurchOrderLinesAndupdateDeliveryRemainder(purchTable.PurchId, true);
                        }
                    }
                     
                    // call if back order is No and journal exist ,any PO line has deliver remainder not equal to zero 
                    if (vendPackingSlipJour.RecId != 0 && metPurchTable.POBackOrderSetting == noyes::No)
                    {
                        PurchLine purchLine;
                        select firstonly RecId from purchLine
                            where purchLine.PurchId == purchTable.PurchId
                                && purchLine.RemainPurchPhysical != 0 && purchLine.IsDeleted == NoYes::No;

                        if (purchLine.RecId)
                        {
                            this.getPurchOrderLinesAndupdateDeliveryRemainder(purchTable.PurchId, true);
                        }
                    }

                }
                catch (Exception::Error)
                {
                    ttsbegin;
                    metPurchTable.selectForUpdate(true);
                    metPurchTable.ProcessingErrorCount += 1;
                    metPurchTable.ProcessingErrorMessage = this.getException();
                    metPurchTable.update();
                    ttscommit;
                }
            }
        }

        /* CB425 BuyBackOrders -start
        Query query;
        QueryRun queryRun;
        QueryBuildDataSource qbdsPurchTable;
        QueryBuildDataSource qbdsMetPurchTable;
        
        InventSite inventSite;
        PurchTable purchTable;
        PurchLine purchLine;
        METPurchLine metPurchLine;
        METPurchTable metPurchTable;
        VendPackingSlipJour vendPackingSlipJour;
        METBackOrderPurchLineTmp metBackOrderPurchLineTmp;

        utcdatetime currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimezone());
        
        date startDate;
        date endDate =  DateTimeUtil::date(currentDateTime);
        int totalDays;
        
        query = _contract.getQuery();
        
        qbdsPurchTable = query.dataSourceTable(tableNum(InventSite)).addDataSource(tableNum(PurchTable));
        qbdsPurchTable.relations(true);
        qbdsPurchTable.joinMode(JoinMode::InnerJoin);
        qbdsPurchTable.addRange(fieldNum(PurchTable, PurchStatus)).value(queryValue(PurchStatus::Backorder));
        
        qbdsMetPurchTable = qbdsPurchTable.addDataSource(tableNum(MetPurchTable));
        qbdsMetPurchTable.relations(true);
        qbdsMetPurchTable.joinMode(JoinMode::InnerJoin);
        qbdsMetPurchTable.addRange(fieldNum(METPurchTable, POBackOrderSetting)).value(queryValue(NoYes::No));
        
        queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            inventSite = null;
            purchTable = null;
            vendPackingSlipJour = null;
            
            inventSite = queryRun.get(tableNum(InventSite));
            purchTable = queryRun.get(tableNum(PurchTable));
            select maxOf(DeliveryDate) from vendPackingSlipJour
                where vendPackingSlipJour.PurchId == purchTable.PurchId;

            if (vendPackingSlipJour.DeliveryDate)
            {
                startDate = vendPackingSlipJour.DeliveryDate;
                totalDays = endDate - startDate; //Calculate number of days from today to last posted product receipt including weekends.
                    
                if (!_contract.parmIncludeWeekends())
                {
                    totalDays = 0;

                    //Calculate number of days from today to last posted product receipt excluding weekends.
                    while (startDate < endDate)
                    {
                        int dayNumber = dayOfWk(startDate);
                        if (dayNumber == 6 || dayNumber == 7) // Saturday or Sunday
                        {
                            startDate++;
                            continue;
                        }
                            
                        totalDays++;
                        startDate++;
                    }
                }

                if (totalDays >= inventSite.METPOBackOrderBatchJobDays)
                {
                    ttsbegin;

                    // Hold Order Qty and Amount in a temp table.
                    insert_recordset metBackOrderPurchLineTmp (PurchId, PurchQty, LineAmount, PurchLineRecId)
                        select PurchId, PurchQty, LineAmount, RecId from purchLine
                            where purchLine.PurchId == purchTable.PurchId;

                    // Cancel PO lines.
                    PurchCancel purchCancel = PurchCancel::METConstruct();
                    purchCancel.parmMetPurchTable(purchTable);
                    purchCancel.run();
                    
                    // Restore Order Qty and Amount from temp table.
                    purchLine.skipDataMethods(true);
                    update_recordset purchLine setting
                        purchQty = metBackOrderPurchLineTmp.PurchQty,
                        LineAmount = metBackOrderPurchLineTmp.LineAmount
                        where purchLine.PurchId == purchTable.PurchId
                    join metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchLineRecId == metPurchLine.purchLine;

                    // Update integration status for PO lines
                    metPurchLine.skipDataMethods(true);
                    update_recordset metPurchLine setting
                        IntegrationStatus = METIntegrationStatus::ReadyToSend
                    join metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchLineRecId == metPurchLine.purchLine;

                    // Update integration status for PO header
                    metPurchTable = METPurchTable::findByPurchTable(purchTable.RecId, true);
                    metPurchTable.doUpdateIntegrationStatus(METIntegrationStatus::ReadyToSend);

                    // Confirm PO
                    this.confirmPO(purchTable);

                    // Empty temp table
                    delete_from metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchId == purchTable.PurchId;

                    ttscommit;
                }
            }
        }
        CB425 BuyBackOrders -end */
    }

    /* CB425 BuyBackOrders -start
    /// <summary>
    /// Confirms the Purchase Order
    /// </summary>
    /// <param name = "_purchTable">The Purchase Order record buffer to be confirmed.</param>
    private void confirmPO(PurchTable _purchTable)
    {
        METVersioningPurchaseOrder                  versioningPurchaseOrder;

        _purchTable.reread(); // Re-read after PO cancellation
        if (_purchTable.ChangeRequestRequired)
        {
            versioningPurchaseOrder = METVersioningPurchaseOrder::newPurchaseOrder(PurchTable::find(_purchTable.PurchId));
            if (_purchTable.canSubmitToWorkflow())
            {
                versioningPurchaseOrder.submitChangeRequest();
                versioningPurchaseOrder.approveChangeRequest();
            }
        }

        _purchTable.reread(); // Re-read after workflow change request approval
        if (_purchTable.DocumentState == VersioningDocumentState::Approved
            && _purchTable.ChangeRequestRequired)
        {
            versioningPurchaseOrder.confirm();
        }
    }
    CB425 BuyBackOrders -end */

    /// CB425 BuyBackOrders
    /// <summary>
    /// Auto workflow purchase order
    /// </summary>
    /// <param name = "_purchId">Purch id</param>
    private void autoWorkflow(PurchId _purchId)
    {
        PurchTable purchTable;

        str comment;
        ttsbegin;
        select forupdate purchTable where purchTable.PurchId  == _purchId;
        comment = strFmt("@MET:METPOFlowSubmited", purchTable.PurchId);

        purchTable.selectForUpdate(true);
        purchTable.submitToWorkflow(workflowTypeStr(PurchTableTemplate), comment, false);
        ttscommit;

        if (purchTable.DocumentState == VersioningDocumentState::InReview)
        {
            Info(comment);
        }
    }

    /// CB425 BuyBackOrders
    /// <summary>
    /// Auto execute the request change
    /// </summary>
    /// <param name = "_purchId">Purch id</param>
    private void autoRequestChange(PurchId _purchId)
    {
        PurchTable purchTable;
       
        ttsbegin;
        select forupdate purchTable where purchTable.PurchId  == _purchId;
        VersioningPurchaseOrder::newPurchaseOrder(purchTable).createChangeRequest();
        ttscommit;

        if (purchTable.DocumentState == VersioningDocumentState::Draft
                    && purchTable.ChangeRequestRequired)
        {
            SourceDocumentHeader    sourceDocumentHeader;
            SourceDocumentLine      sourceDocumentLine;

            sourceDocumentHeader = SourceDocumentHeader::find(purchTable.SourceDocumentHeader);
            AccountingDistributionProcessor::cacheAccountingDistNumbersForHeader(sourceDocumentHeader);

            while select sourceDocumentLine
                        where sourceDocumentLine.SourceDocumentHeader == sourceDocumentHeader.RecId
                        && sourceDocumentLine.ParentSourceDocumentLine == 0
                        && (sourceDocumentLine.AccountingStatus == SourceDocumentLineAccountingStatus::FullyDistributed)
            {
                SourceDocumentProcessorFacade::submitSourceDocumentLineImplementation(sourceDocumentLine.getSourceDocumentLineImplementation(),
                            false,
                            SourceDocumentLineAccountingStatus::Draft);
            }
        }
    }

    /// CB425 BuyBackOrders
    /// <summary>
    /// Get purch order lines and update delivery remainder for purch order lines
    /// </summary>
    /// <param name = "_purchId">Purch id</param>
    /// <param name = "_nonPostJournalPO">Boolean</param>
    private void getPurchOrderLinesAndupdateDeliveryRemainder(PurchId _purchId, boolean _nonPostJournalPO = false)
    {
        #OCCRetryCount

        try
        {
            PurchLine purchLine;
            PurchTable purchTable = PurchTable::find(_purchId, true);
            boolean changeRequestSkip,callbusinessEvent;

            // Auto request change for 208147 Task
            if (!_nonPostJournalPO
                    && purchTable.DocumentState != VersioningDocumentState::Draft)
            {
                this.autoRequestChange(_purchId);
            }

            ttsbegin;
            while select forupdate purchLine
                where purchLine.PurchId == _purchId
                && purchLine.PurchStatus == PurchStatus::Backorder
                && purchLine.IsDeleted == NoYes::No
            {
                callbusinessEvent = true;
                purchLine.reread();
                purchLine.RemainInventPhysical = 0;
                purchLine.RemainPurchPhysical = 0;
                purchLine.PdsCWRemainInventPhysical = 0;
                if (_nonPostJournalPO && purchTable.ChangeRequestRequired)
                {   
                    changeRequestSkip = true;
                    
                    ttsbegin;
                    purchTable.ChangeRequestRequired = NoYes::No;
                    purchTable.doupdate();
                    ttscommit;
                }
                purchLine.update();
            }

            // Run the workflow post the delivery remainder
            if (!_nonPostJournalPO)
            {
                this.autoWorkflow(_purchId);
            }
            ttscommit;

            if (callbusinessEvent && BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(MetPurchLineCancelBusinessEvent)))
            {
                MetPurchLineCancelBusinessEvent::newFromPurchTable(purchTable).send();
            } 
            
            // Set ChangeRequestRequired back to Yes for non post journal PO
            if (changeRequestSkip)
            {
                ttsbegin;
                purchTable.reread();
                purchTable.ChangeRequestRequired = NoYes::Yes;
                purchTable.doupdate();
                ttscommit;
            }
           
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            throw error("@SYS93835");
        }
    }

    /// <summary>
    /// This method will return the exception from the InfoLog
    /// </summary>
    /// <returns>Exception message</returns>
    public Notes getException()
    {
        SysInfologEnumerator infologEnum;
        SysInfologMessageStruct infoLogMessage;
        Notes errorMsg;

        infologEnum = SysInfologEnumerator::newData(infolog.infologData());
        while (infologEnum.moveNext())
        {
            infoLogMessage = SysInfologMessageStruct::construct(infologEnum.currentMessage());
            errorMsg = errorMsg + infoLogMessage.message() + '\n';
        }
        return errorMsg;
    }
